package com.spaceagent.platform.automation;
import com.spaceagent.platform.agent.api.*;import com.spaceagent.platform.agent.domain.AgentDefinitionStatus;import com.spaceagent.platform.automation.api.AutomationTriggerApplicationApi;import com.spaceagent.platform.automation.application.AutomationTriggerApplicationService;import com.spaceagent.platform.automation.domain.*;import com.spaceagent.platform.automation.infrastructure.memory.InMemoryAutomationTriggerRepository;import com.spaceagent.shared.exception.BusinessException;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AutomationTriggerApplicationServiceTest{@Test void managesImmutableLineageAndSubscriptionWithRevisionFence(){var repo=new InMemoryAutomationTriggerRepository();var agents=mock(AgentApplicationApi.class);var agent=mock(AgentDefinitionView.class);when(agent.id()).thenReturn("agent");when(agent.tenantId()).thenReturn("tenant");when(agent.ownerId()).thenReturn("owner");when(agent.status()).thenReturn(AgentDefinitionStatus.ACTIVE);when(agents.findById("agent")).thenReturn(Optional.of(agent));var service=new AutomationTriggerApplicationService(repo,agents,()->Instant.EPOCH);var source=new AutomationTriggerSource.FollowUp("conversation","task",600);var command=new AutomationTriggerApplicationApi.CreateCommand("tenant","owner","agent","follow up","continue",source,"request-001");var draft=service.create(command);assertThat(service.create(command)).isEqualTo(draft);var active=service.activate(new AutomationTriggerApplicationApi.LifecycleCommand("tenant","owner",draft.id(),1));assertThat(active.state()).isEqualTo("ACTIVE");assertThat(repo.findSubscriptionByTrigger(draft.id())).isPresent();var paused=service.pause(new AutomationTriggerApplicationApi.LifecycleCommand("tenant","owner",draft.id(),2));assertThat(service.activate(new AutomationTriggerApplicationApi.LifecycleCommand("tenant","owner",draft.id(),paused.revision())).state()).isEqualTo("ACTIVE");var next=service.createVersion(new AutomationTriggerApplicationApi.CreateVersionCommand("tenant","owner",draft.lineageId(),1,"v2","next",source,"request-v2"));assertThat(next.version()).isEqualTo(2);assertThat(next.previousVersionId()).isEqualTo(draft.id());assertThatThrownBy(()->service.pause(new AutomationTriggerApplicationApi.LifecycleCommand("tenant","owner",draft.id(),1))).isInstanceOf(BusinessException.class);assertThat(service.list(new AutomationTriggerApplicationApi.ListQuery("tenant","owner","agent"))).hasSize(2);}}
